/**
 * The MCP Apps' ui:// resources: the HTML (with the app inlined; pdf.js is not,
 * it loads from the CDN at runtime) and the CSP it runs under.
 *
 * The HTML is generated by scripts/build-mcpapp.mjs. The Worker has no
 * filesystem, so there it is injected as a text module via `setAppHtml`; under
 * Node it is read from dist/mcpapp.
 */
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Resource } from '@modelcontextprotocol/sdk/types.js';
import type { EnvRecord } from '../shared/env.js';
import { toolName } from '../spec/derive.js';
import {
  appCspMeta,
  type AppCsp,
  BEEL_APP_URI,
  INVOICE_PDF_APP_URI,
  INVOICE_PDF_OPERATION,
  MCP_APP_MIME,
  MCP_APPS,
  type McpAppPresentation,
} from './contract.js';

export const invoicePdfAppResource: Resource = {
  uri: INVOICE_PDF_APP_URI,
  name: 'Invoice viewer (PDF)',
  description:
    'Interactive panel that renders the invoice PDF. Opened by the host when ' +
    `${toolName(INVOICE_PDF_OPERATION)} is called.`,
  mimeType: MCP_APP_MIME,
};

export const beelAppResource: Resource = {
  uri: BEEL_APP_URI,
  name: 'BeeL. app',
  description:
    'The invoicing workflow in one panel: setup status, invoices, a single invoice with its ' +
    'actions (issue, send, mark paid, download) and customers. Opened by beel_open_app.',
  mimeType: MCP_APP_MIME,
};

const injected = new Map<string, string>();

/** Inject an app's built HTML; the Worker bundle imports it as a text module. */
export function setAppHtml(uri: string, html: string): void {
  injected.set(uri, html);
}

function resolveHtmlFromDisk(file: string): string | null {
  const here = dirname(fileURLToPath(import.meta.url));
  // From dist/index.js, then from src/mcpapp/*.ts under tsx.
  for (const candidate of [`./mcpapp/${file}`, `../../dist/mcpapp/${file}`]) {
    const path = resolve(here, candidate);
    if (existsSync(path)) return readFileSync(path, 'utf8');
  }
  return null;
}

export interface AppDocument {
  html: string;
  csp: AppCsp;
  presentation: McpAppPresentation;
}

/**
 * An app's HTML, CSP and presentation; `null` when the URI is not an app or its
 * bundle has not been built.
 *
 * The CSP is built here, per read, because it names the deployment's own origin.
 */
export function readApp(uri: string, env?: EnvRecord): AppDocument | null {
  const spec = MCP_APPS[uri];
  if (!spec) return null;
  const html = injected.get(uri) ?? resolveHtmlFromDisk(spec.file);
  if (!html) return null;
  const csp = spec.csp(env);
  return { html: withCspMeta(html, csp), csp, presentation: spec.presentation ?? {} };
}

/** Declare the CSP inside the document too, right after `<head>`. Idempotent. */
export function withCspMeta(html: string, csp: AppCsp): string {
  if (/http-equiv="Content-Security-Policy"/i.test(html)) return html;
  const meta = `<meta http-equiv="Content-Security-Policy" content="${appCspMeta(csp)}" />`;
  return html.replace(/<head>/i, `<head>\n${meta}`);
}
